    }
    else if (ch.metodo === 'setWebhook') linhas.push(`✅ Webhook ligado (${quem.toLowerCase()})`);
    else if (ch.metodo === 'getChat' && r.result.type === 'channel') {
      linhas.push(`✅ Canal: ${r.result.title}`);
