  } else if (temRef90(oferta)) {
    const frase = fraseDesconto(oferta, cfg);
    corpo = [`${formatBRL(oferta.preco)} ${naLoja(oferta.loja)}`, `✅ ${frase.charAt(0).toUpperCase()}${frase.slice(1)}`];
