  const partes = [prefixo || 'bf26', categoria, plataforma, campanha].map(slug);
  if (partes.some((p) => !p)) throw new Error('Sub-ID incompleto: ' + JSON.stringify(partes));
  return { sub_id: partes.join('_'), partes };
}

