function saudeChamadas(cfg) {
  const t = cfg.telegram;
  if (!t.bot_token) return [];
  const out = [chamada('admin', 'getWebhookInfo', {})];
  if (t.dois_bots) out.push(chamada('grupo', 'getWebhookInfo', {}));
