    const fila = Number(w.pending_update_count || 0);
    if (fila > FILA_MAX) {
      out.push({ tipo: `fila_${ch.bot}`, texto: `${quem}: ${fila} atualizações esperando na fila do Telegram. O n8n está atrasado ou fora do ar.` });
