      .filter(([k]) => k !== 'top' && k !== oferta.categoria)
      .map(([k, info]) => ({ text: `↪️ ${info.emoji} ${info.nome.split(' ')[0]}`, callback_data: `m|${k}|${id}` }));
    if (outras.length) linhas.push(outras.slice(0, 4));
