    else if (e.tipo === 'saida' && ultimaEntrada[e.user_hash]) saidas[ultimaEntrada[e.user_hash]] = (saidas[ultimaEntrada[e.user_hash]] || 0) + 1;
  }
  const linhasConvite = Object.entries(porConvite)
    .sort((a, b) => b[1].entradas - a[1].entradas)
    .slice(0, 20)
