/** Payload do /start: "beleza" ou "beleza_meta1" → { categoria, campanha, convite: "beleza_meta1" | "beleza_bot" }. */
function lerStartPayload(payload, cfg) {
  const [catTok, ...resto] = String(payload || '').split('_');
