  const candidatos = [];
  if (ref90 != null) candidatos.push(ref90);
  if (minHistorico != null && (historicoCompleto || ref90 != null)) candidatos.push(minHistorico);
  const min90 = candidatos.length ? Math.min(...candidatos) : null;

