  if (oferta.vendas) extra.push(`${oferta.vendas} vendidos`);
  if (oferta.top) extra.push('⭐ marcada para o Top do Dia');
  if (cupomDe(oferta)) extra.push(`🎟️ cupom ${cupomDe(oferta)}`);
