    `<b>${escapeHtml(truncar(oferta.titulo, 200))}</b>`,
    `${escapeHtml(nomeLoja(oferta.loja))} · ${linhaPrecoCard}`,
    `Menor 90d: ${ref}${desc}${origem ? ' · origem: ' + escapeHtml(origem) : ''}${fonte}`,
  ];
