  const podePublicar = permitePublicarSelo(oferta, cfg) && semBloqueio;
  const teclado = [];
  if (podePublicar) {
    teclado.push([
      { text: '✅ Aprovar', callback_data: `a|${id}` },
      { text: '⚡ Relâmpago', callback_data: `r|${id}` },
    ]);
