    sephora: 'sephora',
  };
  const cats = Object.keys((cfg && cfg.categorias) || CATEGORIAS).filter((c) => c !== 'top');
  const apelidosBusca = { games: 'tech', gamer: 'tech', game: 'tech', informatica: 'tech', saude: 'beleza' };
