    .filter((s) => s.includes('-') && /[a-z]{3,}/i.test(s) && !/^(sec|gz|social|account-verification|universal-link|opaanlp|product|dp|gp)$/i.test(s))
    .sort((a, b) => b.length - a.length);
  return candidatos.length ? humanizarSlug(candidatos[0]) : '';
}

