  return {
    proximo: 'publicar',
    so_textos: false,
    chamadas: [responder('Publicando…'), marcar('⏳ Publicando…')],
    update: Object.assign(base, { status: 'publicando', relampago: pub.relampago, top: pub.top }),
    oferta: pub,
    linkItens,
  };
}

