const SIGLAS = new Set([
  'tv', 'ssd', 'hd', 'nvme', 'usb', 'usbc', 'hdmi', 'tws', 'led', 'rgb', 'qled', 'oled', 'uhd', 'fhd',
  '4k', '8k', '5g', '4g', 'wifi', 'anc', 'jbl', 'lg', 'hp', 'ps5', 'ps4', 'pc', 'cpu', 'gpu',
