    else if (CATEGORIA_PADRAO_LOJA[o.loja]) o.categoria = CATEGORIA_PADRAO_LOJA[o.loja];
  }

  if (o.preco == null) {
    return { rota: 'responder', chamadas: [pedirPrecoRapido(e, cfg)] };
  }
  if (!o.titulo) {
    o.titulo = tituloDaUrl(o.url_original || o.url) || `Oferta ${nomeLoja(o.loja)}`;
  }
  return e;
}

