    const nd = extrairNextData(html);
    if (nd) {
      if (!out.titulo && nd.titulo) out.titulo = nd.titulo;
      if (!out.preco && nd.preco) out.preco = nd.preco;
      if (!out.preco_de && nd.preco_de) out.preco_de = nd.preco_de;
