    const mCupPctAmz = textoCupAmz.match(/(?:salve|marque|aplique|aplicar)\s+o\s+cupom(?:\s+de)?\s*(\d{1,2})\s*%|(?:cupom(?:\s+de)?|economize(?:\s+mais)?)\s*(\d{1,2})\s*%/i);
