    const mCupValAmz = !out.cupom_pct && textoCupAmz.match(/(?:salve|marque|aplique|aplicar)\s+o\s+cupom(?:\s+de)?\s*R\$\s*([\d.]+(?:,\d{2})?)|(?:cupom(?:\s+de)?|economize(?:\s+mais)?)\s*R\$\s*([\d.]+(?:,\d{2})?)/i);
