function problemasSaude(chamadas, respostas, cfg, agora) {
  const esperado = cfg.telegram.n8n_webhook_url;
  const out = [];
  chamadas.forEach((ch, i) => {
    const quem = QUEM[ch.bot] || ch.bot;
    const r = respostas[i] || {};
