        tipo: `url_${ch.bot}`,
        texto: w.url
          ? `${quem}: o webhook aponta para outro endereço (${w.url}). Rode o 00 · Setup ou reinicie o vigia.`
          : `${quem}: o webhook está desligado. Rode o 00 · Setup ou reinicie o vigia.`,
