}

const MEMBRO = ['member', 'administrator', 'creator', 'restricted'];

function ehMembro(cm) {
  if (!cm) return false;
  if (cm.status === 'restricted') return cm.is_member !== false;
  return MEMBRO.includes(cm.status);
