// Antispam do 💬 Conversa: convites de outros grupos, WhatsApp e encurtadores (inclusive links curtos de afiliado).
const SPAM = new RegExp([
  '(?:^|[^\\w.-])(?:t|telegram)\\.(?:me|dog)/',
  'chat\\.whatsapp\\.com',
  'api\\.whatsapp\\.com',
  '(?:^|[^\\w.-])wa\\.me/',
