    if (low === 'bivolt' || low === 'bluetooth' || low === 'kit') return low.charAt(0).toUpperCase() + low.slice(1);
    if (SIGLAS.has(low)) return low.toUpperCase();
    return w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
  });
  return truncar(fmt.join(' '), 180);
}

