      const s = saidas[nome] || 0;
      const ret = v.entradas ? Math.round(((v.entradas - s) / v.entradas) * 100) : 0;
      return `  ${nome}: +${v.hoje} hoje · ${v.entradas} total · ${s} saíram · retenção ${ret}%`;
    });

