    linhasConvite.join('\n') || '  —',
    ...(entHoje.some((e) => e.tipo === 'start') ? ['', `/start no bot publicador hoje: ${entHoje.filter((e) => e.tipo === 'start').length}`, fmt(conta(entHoje.filter((e) => e.tipo === 'start'), 'convite_nome'))] : []),
    '',
