  const lojasDica = Object.values(semAfiliado);
  if (lojasDica.length) {
    linhasRel.push('', `💰 Publicadas hoje sem seu código de afiliado: ${lojasDica.map((d) => d.nome).join(', ')} → veja /afiliados`);
